const formulario=document.getElementById("formulario-tarea"),tituloTarea=document.getElementById("titulo-tarea"),prioridadTarea=document.getElementById("prioridad-tarea"),listaTareas=document.getElementById("lista-tareas"),totalTareas=document.getElementById("total-tareas"),pendientesTareas=document.getElementById("pendientes-tareas"),completadasTareas=document.getElementById("completadas-tareas"),filtros=document.querySelectorAll(".filtro");let tareas=JSON.parse(localStorage.getItem("taskflow-tareas"))||[],filtroActual="todas";function guardarTareas(){localStorage.setItem("taskflow-tareas",JSON.stringify(tareas))}function generarId(){return Date.now()}function agregarTarea(a){a.preventDefault();const e=tituloTarea.value.trim();if(!e)return;const t={id:generarId(),titulo:e,prioridad:prioridadTarea.value,completada:!1,fechaCreacion:(new Date).toISOString()};tareas.push(t),guardarTareas(),formulario.reset(),prioridadTarea.value="media",mostrarTareas()}function eliminarTarea(a){const e=tareas.find(e=>e.id===a);if(!e)return;confirm(`¿Seguro que deseas eliminar la tarea "${e.titulo}"?`)&&(tareas=tareas.filter(e=>e.id!==a),guardarTareas(),mostrarTareas())}function cambiarEstado(a){tareas=tareas.map(e=>e.id===a?{...e,completada:!e.completada}:e),guardarTareas(),mostrarTareas()}function obtenerTareasFiltradas(){return"pendientes"===filtroActual?tareas.filter(a=>!a.completada):"completadas"===filtroActual?tareas.filter(a=>a.completada):tareas}function formatearFecha(a){return a?new Date(a).toLocaleString("es-MX",{dateStyle:"medium",timeStyle:"short"}):"Fecha no disponible"}function crearElementoTarea(a){const e=document.createElement("article");return e.className=`tarea prioridad-${a.prioridad}`,a.completada&&e.classList.add("tarea-completada"),e.innerHTML=`\n        <div class="tarea-info">\n            <div class="tarea-titulo">${a.titulo}</div>\n            <span class="tarea-prioridad">\n            Prioridad: ${a.prioridad.toUpperCase()}\n            </span>\n            <span class="tarea-fecha">\n            Creada: ${formatearFecha(a.fechaCreacion)}\n            </span>\n        </div>\n\n        <div class="tarea-acciones">\n            <button\n                class="boton boton-secundario"\n                data-accion="estado"\n                data-id="${a.id}">\n                ${a.completada?"Reabrir":"Completar"}\n            </button>\n\n            <button\n                class="boton boton-eliminar"\n                data-accion="eliminar"\n                data-id="${a.id}">\n                Eliminar\n            </button>\n        </div>\n    `,e}function mostrarTareas(){const a=obtenerTareasFiltradas();listaTareas.innerHTML="",0===a.length?listaTareas.innerHTML='\n            <div class="mensaje-vacio">\n                <p>No hay tareas para mostrar.</p>\n                <span>Agrega una nueva tarea para comenzar.</span>\n            </div>\n        ':a.forEach(a=>{listaTareas.appendChild(crearElementoTarea(a))});const e=tareas.length,t=tareas.filter(a=>a.completada).length,r=e-t;totalTareas.textContent=e,pendientesTareas.textContent=r,completadasTareas.textContent=t}function cambiarFiltro(a){filtroActual=a,filtros.forEach(e=>{e.classList.toggle("activo",e.dataset.filtro===a)}),mostrarTareas()}formulario.addEventListener("submit",agregarTarea),listaTareas.addEventListener("click",a=>{const e=a.target.closest("button");if(!e)return;const t=Number(e.dataset.id),r=e.dataset.accion;"estado"===r&&cambiarEstado(t),"eliminar"===r&&eliminarTarea(t)}),filtros.forEach(a=>{a.addEventListener("click",()=>{cambiarFiltro(a.dataset.filtro)})}),mostrarTareas();